'use strict';

// MODULES //

var serialize = require( '@stdlib/ndarray/base/serialize-meta-data' );
var getData = require( '@stdlib/ndarray/base/data-buffer' );
var reinterpretBoolean = require( '@stdlib/strided/base/reinterpret-boolean' );
var addon = require( './../src/addon.node' );


// MAIN //

/**
* Takes elements from one of two one-dimensional single-precision floating-point ndarrays depending on a condition.
*
* @private
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @returns {ndarray} output ndarray
*/
function swhere( arrays ) {
	var condition = arrays[ 0 ];
	var out = arrays[ 3 ];
	var x = arrays[ 1 ];
	var y = arrays[ 2 ];
	addon( reinterpretBoolean( getData( condition ), 0 ), serialize( condition ), getData( x ), serialize( x ), getData( y ), serialize( y ), getData( out ), serialize( out ) ); // eslint-disable-line max-len
	return out;
}


// EXPORTS //

module.exports = swhere;
